        lat: 37.3988837, lng: -5.9937356,
        description: {
          es: 'El paseo más antiguo de Europa, sobre lo que fue la Laguna de la Feria. Las columnas de Hércules y Julio César vigilan desde el siglo XVI.',
          en: 'Europe\'s oldest promenade, built over the former Laguna de la Feria. The Hercules and Julius Caesar columns have watched over it since the 16th century.',
          fr: 'La plus ancienne promenade d\'Europe, sur l\'ancienne Laguna de la Feria. Les colonnes d\'Hercule et Jules César veillent depuis le XVIe siècle.',
          de: 'Europas älteste Promenade, auf der einstigen Laguna de la Feria. Die Säulen von Herkules und Julius Cäsar wachen seit dem 16. Jh.',
          it: 'La passeggiata più antica d\'Europa, sull\'ex Laguna de la Feria. Le colonne di Ercole e Giulio Cesare vegliano dal XVI secolo.',
          pt: 'O passeio mais antigo da Europa, sobre a antiga Laguna de la Feria. As colunas de Hércules e Júlio César vigiam desde o século XVI.',
        },
        tip: {
          es: 'La leyenda dice que Hércules (el navegante fenicio Melkart) fundó Sevilla aquí al remontar el río. Y en esta misma laguna fue quemada por traidora doña Urraca Ossorio: al alzarse sus faldas con el calor del fuego, gritó de pudor ante la multitud. El mausoleo con su estatua yacente está en San Isidoro del Campo.',
          en: 'Legend says Hercules (the Phoenician sailor Melkart) founded Seville here sailing up the river. And on this very lagoon doña Urraca Ossorio was burned for treason: as the fire lifted her skirts, she cried out in shame before the crowd. Her tomb with a recumbent statue is at San Isidoro del Campo.',
          fr: 'La légende dit qu\'Hercule (le marin phénicien Melkart) fonda Séville ici. Et sur cette même lagune, doña Urraca Ossorio fut brûlée pour trahison : la chaleur soulevant ses jupes, elle cria de pudeur devant la foule.',
          de: 'Der Legende nach gründete Herkules (der phönizische Seefahrer Melkart) hier Sevilla. Und auf dieser Lagune wurde doña Urraca Ossorio als Verräterin verbrannt: Als die Hitze ihre Röcke hob, schrie sie vor Scham.',
          it: 'La leggenda dice che Ercole (il navigatore fenicio Melkart) fondò qui Siviglia. E su questa laguna fu bruciata per tradimento doña Urraca Ossorio: quando il calore sollevò le sue gonne, gridò di pudore.',
          pt: 'A lenda diz que Hércules (o navegador fenício Melkart) fundou aqui Sevilha. E nesta lagoa foi queimada por traição doña Urraca Ossorio: quando o calor levantou as suas saias, gritou de pudor.',
        },
