        tip: {
          es: 'Tras la conquista, el rey Santo regaló al almirante Bonifaz unas casas en esta calle, en el Repartimiento. La leyenda se toca: los soportales donde hoy pasean los turistas fueron el premio al hombre que rompió la cadena del río.',
          en: 'After the conquest, the Saint King gifted Admiral Bonifaz houses on this street in the Repartimiento. The legend is tangible: the arcades tourists stroll today were the prize for the man who broke the river\'s chain.',
          fr: 'Après la conquête, le roi Saint offrit à l\'amiral Bonifaz des maisons dans cette rue lors du Repartimiento. La légende se touche : les arcades d\'aujourd\'hui furent la récompense de celui qui brisa la chaîne.',
          de: 'Nach der Eroberung schenkte der heilige König Admiral Bonifaz Häuser in dieser Straße beim Repartimiento. Die Legende ist greifbar: Die heutigen Arkaden waren der Lohn des Mannes, der die Kette brach.',
          it: 'Dopo la conquista, il re Santo regalò all\'ammiraglio Bonifaz delle case in questa via nel Repartimiento. La leggenda si tocca: i portici di oggi furono il premio di chi spezzò la catena.',
          pt: 'Após a conquista, o Rei Santo ofereceu ao almirante Bonifaz casas nesta rua no Repartimiento. A lenda toca-se: as arcadas de hoje foram o prémio de quem rompeu a corrente do rio.',
        },
