          en: 'Triana sanctuary of the Cristo de la Expiración, the neighbourhood\'s most beloved image after the Esperanza de Triana.',
          fr: 'Sanctuaire trianero du Christ de l\'Expiration, l\'image la plus aimée du quartier après l\'Esperanza de Triana.',
          de: 'Trianas Heiligtum des Cristo de la Expiración, das beliebteste Bild des Viertels nach der Esperanza de Triana.',
