      es: 'Cuando Sevilla era capital de un imperio: la Giralda recién construida, la muralla, la cadena del río y las iglesias que aún esconden sus minaretes. Un paseo por la ciudad de 1198.',
      en: 'When Seville was the capital of an empire: the newly built Giralda, the city wall, the river chain and the churches that still hide their minarets. A walk through the city of 1198.',
