      en: 'Seville\'s 18th century from within: frescoed domes, gilded altarpieces and the church that aspired to be "the Pantheon of Andalusian Baroque". Gold, plaster and trompe-l\'oeil.',
      fr: 'Le XVIIIe siècle sévillan de l\'intérieur : coupoles fresquées, retables dorés et l\'église qui voulait être "le Panthéon du baroque andalou".',
