          de: 'Der almohadische Turm von 1221, der den Fluss mit einer Kette verschloss. Sein Schifffahrtsmuseum voller Modelle und Navigationsinstrumente erklimmt man über eine Wendeltreppe, die Kinder für ein Schloss halten.',
          it: 'La torre almohade del 1221 che chiudeva il fiume con una catena. Il suo belvedere marittimo, pieno di modellini e strumenti di navigazione, si sale da una scala a chiocciola che ai bambini sembra un castello.',
