          en: 'Very cheap entry (under 5€, young children free). From the top, the views of the river and the bullring are the best around. Queues are usually short in the mid-afternoon.',
          fr: 'Entrée très économique (moins de 5€, petits gratuits jusqu\'à un certain âge). Du haut, les vues sur le fleuve et les arènes sont les meilleures du quartier. File d\'attente généralement courte en milieu d\'après-midi.',
