    title: {
      es: 'Bicis y trenecito: el parque del Alamillo en familia',
      en: 'Bikes and mini-train: Alamillo Park with the family',
      fr: 'Vélos et petit train : le parc de l\'Alamillo en famille',
      de: 'Fahrräder und Bähnchen: der Alamillo-Park mit der Familie',
      it: 'Bici e trenino: il parco dell\'Alamillo in famiglia',
      pt: 'Bicicletas e comboio: o parque do Alamillo em família',
    },
    description: {
      es: 'Cruzar el río por la Barqueta y perderse en un parque de 120 hectáreas sin un solo coche: carril bici, trenecito, columpios, kioscos y el puente de Calatrava como telón de fondo.',
      en: 'Cross the river by the Barqueta bridge and get lost in 120 car-free hectares: bike lanes, a mini-train, playgrounds, kiosks and Calatrava\'s bridge as a backdrop.',
      fr: 'Traverser le fleuve par la Barqueta et se perdre dans 120 hectares sans une seule voiture : piste cyclable, petit train, balançoires, kiosques et le pont de Calatrava en toile de fond.',
      de: 'Über die Barqueta-Brücke den Fluss queren und in 120 autofreien Hektar verschwinden: Radweg, Bähnchen, Spielplätze, Kioske und Calatravas Brücke als Kulisse.',
      it: 'Attraversare il fiume dalla Barqueta e perdersi in 120 ettari senza auto: pista ciclabile, trenino, scivoli, chioschi e il ponte di Calatrava sullo sfondo.',
      pt: 'Atravessar o rio pela Barqueta e perder-se em 120 hectares sem um único carro: pista ciclável, comboio turístico, escorregas, quiosques e a ponte de Calatrava como pano de fundo.',
    },
    intro: {
      es: 'El parque del Alamillo nació con la Expo 92 como jardín de la isla de la Cartuja y hoy es el patio de juegos más grande de Sevilla: 120 hectáreas de praderas, naranjos y carril bici donde los coches no existen. Los fines de semana mueven un trenecito turístico, hay zonas de columpios y kioscos con sombra, y junto al parque se alza el puente del Alamillo, la obra más famosa de Calatrava en la ciudad, con su mástil inclinado y su única pila. En familia se recorre en bici (alquiler en el centro o en el propio parque), y para los que prefieren andar, el paseo desde la Barqueta ya es un espectáculo. Llevad gorras y agua: hay pocas sombras en las praderas.',
      en: 'Alamillo Park was born with Expo 92 as the garden of the Cartuja island and is today Seville\'s biggest playground: 120 hectares of meadows, orange trees and bike lanes where cars do not exist. At weekends a mini-train runs, there are playgrounds and shaded kiosks, and next to the park stands the Alamillo bridge, Calatrava\'s most famous work in the city, with its leaning mast and single pylon. Families ride it by bike (rented in the centre or in the park itself), and for those who prefer walking, the stroll from the Barqueta is already a spectacle. Take caps and water: the meadows offer little shade.',
      fr: 'Le parc de l\'Alamillo est né avec l\'Expo 92 comme jardin de l\'île de la Cartuja et constitue aujourd\'hui le plus grand terrain de jeux de Séville : 120 hectares de prairies, d\'orangers et de pistes cyclables où les voitures n\'existent pas. Le week-end, un petit train circule, il y a des aires de jeux et des kiosques ombragés, et à côté du parc se dresse le pont de l\'Alamillo, l\'œuvre la plus célèbre de Calatrava dans la ville, avec son mât incliné et son unique pylône. En famille, on le parcourt à vélo (location au centre-ville ou dans le parc), et pour ceux qui préfèrent marcher, la promenade depuis la Barqueta est déjà un spectacle. Prenez casquettes et eau : les prairies offrent peu d\'ombre.',
      de: 'Der Alamillo-Park entstand mit der Expo 92 als Garten der Cartuja-Insel und ist heute der größte Spielplatz Sevillas: 120 Hektar Wiesen, Orangenbäume und Radwege, auf denen es keine Autos gibt. Am Wochenende fährt ein Bähnchen, es gibt Spielplätze und schattige Kioske, und neben dem Park steht die Alamillo-Brücke, Calatravas berühmtestes Werk der Stadt, mit ihrem geneigten Mast und dem einzigen Pfeiler. Familien fahren mit dem Rad (Verleih im Zentrum oder im Park), und wer lieber geht, für den ist schon der Weg von der Barqueta ein Schauspiel. Nehmt Kappen und Wasser mit: Die Wiesen spenden wenig Schatten.',
      it: 'Il parco dell\'Alamillo è nato con l\'Expo 92 come giardino dell\'isola della Cartuja e oggi è il parco giochi più grande di Siviglia: 120 ettari di prati, aranci e piste ciclabili dove le auto non esistono. Nei fine settimana circola un trenino, ci sono aree giochi e chioschi ombreggiati, e accanto al parco si erge il ponte dell\'Alamillo, l\'opera più famosa di Calatrava in città, con l\'albero inclinato e l\'unica pila. In famiglia si percorre in bici (noleggio in centro o nel parco), e per chi preferisce camminare, la passeggiata dalla Barqueta è già uno spettacolo. Portate cappellini e acqua: i prati offrono poca ombra.',
      pt: 'O parque do Alamillo nasceu com a Expo 92 como jardim da ilha da Cartuja e é hoje o maior parque infantil de Sevilha: 120 hectares de prados, laranjeiras e pistas cicláveis onde os carros não existem. Aos fins de semana circula um comboio turístico, há zonas de escorregas e quiosques com sombra, e junto ao parque ergue-se a ponte do Alamillo, a obra mais famosa de Calatrava na cidade, com o seu mastro inclinado e o único pilar. Em família percorre-se de bicicleta (aluguer no centro ou no próprio parque), e para quem prefere andar, o passeio desde a Barqueta já é um espetáculo. Levem bonés e água: os prados dão pouca sombra.',
    },
    transportDetails: {
      es: 'Bici por el carril bici (desde el centro, 20 min hasta la Barqueta) o taxi (8-10 min desde el apartamento). El parque tiene alquiler de bicicletas y el trenecito funciona los fines de semana. Sevici dispone de estaciones en la zona de la Alameda.',
      en: 'Bike along the bike lane (from the centre, 20 min to the Barqueta) or taxi (8-10 min from the apartment). The park rents bicycles and the mini-train runs at weekends. Sevici has stations in the Alameda area.',
      fr: 'À vélo par la piste cyclable (depuis le centre, 20 min jusqu\'à la Barqueta) ou en taxi (8-10 min depuis l\'appartement). Le parc loue des vélos et le petit train circule le week-end. Sevici dispose de stations du côté de l\'Alameda.',
      de: 'Mit dem Rad auf dem Radweg (vom Zentrum 20 Min. bis zur Barqueta) oder per Taxi (8-10 Min. von der Wohnung). Im Park gibt es Fahrradverleih, das Bähnchen fährt am Wochenende. Sevici hat Stationen im Bereich der Alameda.',
      it: 'In bici sulla pista ciclabile (dal centro, 20 min fino alla Barqueta) o in taxi (8-10 min dall\'appartamento). Il parco noleggia biciclette e il trenino circola nei fine settimana. Sevici ha stazioni nella zona dell\'Alameda.',
      pt: 'De bicicleta pela pista ciclável (do centro, 20 min até à Barqueta) ou de táxi (8-10 min desde o apartamento). O parque aluga bicicletas e o comboio circula aos fins de semana. A Sevici tem estações na zona da Alameda.',
    },
