          de: 'Der Park wurde 1993 auf dem Gelände der Expo 92 eröffnet, um der Stadt eine große Grünfläche auf der Insel zurückzugeben. Seinen Namen trägt er nach dem alten Gutshof Alamillo, der schon auf Plänen des 18. Jahrhunderts erscheint.',
