          fr: 'Point de départ vers la cathédrale : bus C1/C2 ou taxi (10 min). Aujourd\'hui, Séville se raconte comme un conte.',
          de: 'Startpunkt Richtung Kathedrale: Bus C1/C2 oder Taxi (10 Min.). Heute wird Sevilla als Märchen erzählt.',
          it: 'Punto di partenza verso la Cattedrale: bus C1/C2 o taxi (10 min). Oggi Siviglia si racconta come una fiaba.',
