          de: 'Erzählt den Kindern vor dem Aufbruch, dass sie ein in der Kathedrale verstecktes Krokodil finden werden: Die Eidechsenjagd fesselt sie vom ersten Schritt an.',
          it: 'Prima di partire, raccontate ai bambini che cercheranno un coccodrillo nascosto nella Cattedrale: la caccia al lucertolone li cattura dal primo passo.',
