          en: 'The tower watching over Seville for eight centuries has no stairs: it has ramps, because its guardians climbed on horseback. It is crowned by a weathervane that turns with the wind, the Giraldillo.',
          fr: 'La tour qui veille sur Séville depuis huit siècles n\'a pas d\'escaliers : elle a des rampes, car ses gardiens montaient à cheval. La couronne une girouette qui tourne au vent, le Giraldillo.',
          de: 'Der Turm, der seit acht Jahrhunderten über Sevilla wacht, hat keine Treppen: Er hat Rampen, denn seine Wächter stiegen zu Pferde hinauf. Gekrönt wird er von einer Wetterfahne, die sich mit dem Wind dreht, dem Giraldillo.',
          it: 'La torre che veglia Siviglia da otto secoli non ha scale: ha rampe, perché le sue guardie salivano a cavallo. La corona una banderuola che gira col vento, la Giraldilla.',
          pt: 'A torre que vigia Sevilha há oito séculos não tem escadas: tem rampas, porque os seus guardas subiam a cavalo. Coroa-a um cata-vento que gira com o vento, o Giraldillo.',
