          de: 'Ein Palast des 16. Jahrhunderts, der Mudéjar, Gotik und Renaissance mischt, der Legende nach als Kopie des Hauses von Pontius Pilatus in Jerusalem. Seine Höfe und Kacheln stehen dem Alcázar kaum nach.',
          it: 'Un palazzo del Cinquecento che mescola mudéjar, gotico e rinascimento, costruito secondo la leggenda come copia della casa di Ponzio Pilato a Gerusalemme. I suoi patii e azulejos rivaleggiano con quelli dell\'Alcázar.',
          pt: 'Um palácio do século XVI que mistura mudéjar, gótico e renascimento, construído segundo a lenda como cópia da casa de Pôncio Pilatos em Jerusalém. Os seus pátios e azulejos rivalizam com os do Alcázar.',
