          en: 'The ground floor and gardens are visited with a cheap ticket. Films such as Lawrence of Arabia were shot here: the courtyards feel like another age.',
          fr: 'Le rez-de-chaussée et les jardins se visitent avec un billet économique. Des films comme Lawrence d\'Arabie y ont été tournés : les patios semblent d\'une autre époque.',
          de: 'Erdgeschoss und Gärten besucht man mit günstigem Ticket. Filme wie Lawrence von Arabien wurden hier gedreht: Die Höfe wirken wie aus einer anderen Zeit.',
          it: 'Il piano terra e i giardini si visitano con biglietto economico. Qui sono stati girati film come Lawrence d\'Arabia: i patii sembrano di un\'altra epoca.',
